function climbStairs(n: number): number {
  // dp[i] — число способов дойти до ступеньки i.
  // На ступеньку i попадаем либо с i - 1 (шаг 1), либо с i - 2 (шаг 2):
  // dp[i] = dp[i - 1] + dp[i - 2]. Хватит двух последних значений.
  let prev = 1; // dp[0]: один способ — стоять на месте
  let curr = 1; // dp[1]: один способ — шаг на 1

  for (let i = 2; i <= n; i++) {
    const next = prev + curr;
    // Сдвигаем «окно» из двух значений на одну ступеньку вверх
    prev = curr;
    curr = next;
  }

  return curr;
}

// Время: O(n)
// Память: O(1) — вместо массива dp храним два числа
